CREATE TABLE IF NOT EXISTS project_deletions (project_id TEXT PRIMARY KEY, deleted_at TEXT NOT NULL, permanent INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(project_id) REFERENCES projects(id));
DROP TRIGGER IF EXISTS immutable_messages_delete;
CREATE TRIGGER IF NOT EXISTS immutable_messages_delete BEFORE DELETE ON messages WHEN NOT EXISTS(SELECT 1 FROM project_deletions WHERE project_id=OLD.project_id AND permanent=1) BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
DROP TRIGGER IF EXISTS immutable_artifacts_delete;
CREATE TRIGGER IF NOT EXISTS immutable_artifacts_delete BEFORE DELETE ON artifacts WHEN NOT EXISTS(SELECT 1 FROM project_deletions WHERE project_id=OLD.project_id AND permanent=1) BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
