DROP TRIGGER IF EXISTS confirmed_policy_delete;
CREATE TRIGGER IF NOT EXISTS confirmed_policy_delete BEFORE DELETE ON assessment_policies WHEN OLD.status='confirmed' AND NOT EXISTS(SELECT 1 FROM project_deletions WHERE project_id=OLD.project_id AND permanent=1) BEGIN SELECT RAISE(ABORT,'IMMUTABLE_POLICY'); END;
